{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "EVT 301, a primary amide plus halogenated anilide-like structure, crossed the human BBB and produced >90% brain MAO-B occupancy in a PET study, providing direct human evidence that this chemotype achieves meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "18F-LY2459989, a KOR antagonist containing a primary carboxamide and halogenated aryl groups, showed high brain uptake in nonhuman primates, supporting CNS access for amide-rich halogenated aromatic compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "ICI 197067, a dichlorophenyl-containing amide, reached measurable brain concentrations (119 pg/mg tissue) and elicited centrally mediated effects, demonstrating that dichloroanilide/amide scaffolds can penetrate the BBB in vivo.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Cyheptamide, a primary amide, showed close brain and serum concentration similarity in rats, indicating that a primary carboxamide does not prevent ready BBB passage.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "PNU282987, a chlorophenyl amide, was detected in brain after intravenous administration and reported to have good brain penetration, supporting CNS access for chlorophenyl amide-containing molecules.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass: multiple high-transfer direct in vivo, PET, and brain-concentration experiments on structurally related primary amide and halogenated anilide/amide compounds consistently demonstrate meaningful CNS access, with no contradictory evidence.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule.",
    "No explicit efflux-transporter data for the query.",
    "Stereochemistry and metabolic stability of the query were not experimentally assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

